UPDATE sys_module
SET sort = CASE
    WHEN id = #{id} THEN #{newSort}
    WHEN #{newSort} < #{oldSort}
        AND sort >= #{newSort}
        AND sort < #{oldSort} THEN sort + 1
    WHEN #{newSort} > #{oldSort}
        AND sort <= #{newSort}
        AND sort > #{oldSort} THEN sort - 1
    ELSE sort
END
WHERE (sort BETWEEN LEAST(#{oldSort}, #{newSort}) AND GREATEST(#{oldSort}, #{newSort}))
    OR id = #{id}

